1	export const SCHEDULE_AXIS_LAYOUTS = [
2	  'time-top-resource-left',
3	  'time-left-resource-top',
4	] as const;
5	
6	export type ScheduleAxisLayout = (typeof SCHEDULE_AXIS_LAYOUTS)[number];
7	export type ScheduleCardDisplayMode = 'compact' | 'expanded';
8	export type ScheduleViewMode = 'timeline' | 'list';
9	
10	export type ScheduleVisualConfig = {
11	  axisLayout: ScheduleAxisLayout;
12	  cardDisplayMode: ScheduleCardDisplayMode;
13	  timelineStartHour: number;
14	  visibleResourceTypes: string[];
15	  visibleAdminIds: string[] | null;
16	  collapsedResourceTypes: string[];
17	  viewMode: ScheduleViewMode;
18	  aircraftAutoSortByMaintenance: boolean;
19	};
20	
21	export type PartialScheduleVisualConfig = Partial<ScheduleVisualConfig>;
22	
23	export const DEFAULT_SCHEDULE_VISIBLE_RESOURCE_TYPES = [
24	  'aircraft',
25	  'simulator',
26	  'instructor',
27	  'admin',
28	  'meeting_room',
29	] as const;
30	
31	export const DEFAULT_SCHEDULE_VISUAL_CONFIG: ScheduleVisualConfig = {
32	  axisLayout: 'time-top-resource-left',
33	  cardDisplayMode: 'expanded',
34	  timelineStartHour: 5,
35	  visibleResourceTypes: [...DEFAULT_SCHEDULE_VISIBLE_RESOURCE_TYPES],
36	  visibleAdminIds: null,
37	  collapsedResourceTypes: [],
38	  viewMode: 'timeline',
39	  aircraftAutoSortByMaintenance: false,
40	};
41	
42	const resourceTypeSet = new Set<string>(
43	  DEFAULT_SCHEDULE_VISIBLE_RESOURCE_TYPES,
44	);
45	const axisLayoutSet = new Set<string>(SCHEDULE_AXIS_LAYOUTS);
46	
47	function isRecord(value: unknown): value is Record<string, unknown> {
48	  return typeof value === 'object' && value !== null && !Array.isArray(value);
49	}
50	
51	function uniqueStrings(value: unknown): string[] | undefined {
52	  if (!Array.isArray(value)) return undefined;
53	  return [
54	    ...new Set(
55	      value.filter((item): item is string => typeof item === 'string'),
56	    ),
57	  ];
58	}
59	
60	function visibleResourceTypes(value: unknown): string[] | undefined {
61	  const strings = uniqueStrings(value);
62	  if (!strings) return undefined;
63	  return strings.filter((item) => resourceTypeSet.has(item));
64	}
65	
66	function visibleAdminIds(value: unknown): string[] | null | undefined {
67	  if (value === null) return null;
68	  return uniqueStrings(value);
69	}
70	
71	function collapsedResourceTypes(value: unknown): string[] | undefined {
72	  const strings = uniqueStrings(value);
73	  if (!strings) return undefined;
74	  return strings.filter((item) => resourceTypeSet.has(item));
75	}
76	
77	export function readScheduleVisualConfig(
78	  value: unknown,
79	): PartialScheduleVisualConfig | null {
80	  if (!isRecord(value)) return null;
81	
82	  const next: PartialScheduleVisualConfig = {};
83	
84	  if (
85	    typeof value.axisLayout === 'string' &&
86	    axisLayoutSet.has(value.axisLayout)
87	  ) {
88	    next.axisLayout = value.axisLayout as ScheduleAxisLayout;
89	  }
90	
91	  if (
92	    value.cardDisplayMode === 'compact' ||
93	    value.cardDisplayMode === 'expanded'
94	  ) {
95	    next.cardDisplayMode = value.cardDisplayMode;
96	  }
97	
98	  if (
99	    typeof value.timelineStartHour === 'number' &&
100	    Number.isInteger(value.timelineStartHour) &&
101	    value.timelineStartHour >= 0 &&
102	    value.timelineStartHour < 24
103	  ) {
104	    next.timelineStartHour = value.timelineStartHour;
105	  }
106	
107	  const types = visibleResourceTypes(value.visibleResourceTypes);
108	  if (types !== undefined) next.visibleResourceTypes = types;
109	
110	  const adminIds = visibleAdminIds(value.visibleAdminIds);
111	  if (adminIds !== undefined) next.visibleAdminIds = adminIds;
112	
113	  const collapsed = collapsedResourceTypes(value.collapsedResourceTypes);
114	  if (collapsed) next.collapsedResourceTypes = collapsed;
115	
116	  if (value.viewMode === 'timeline' || value.viewMode === 'list') {
117	    next.viewMode = value.viewMode;
118	  }
119	
120	  if (typeof value.aircraftAutoSortByMaintenance === 'boolean') {
121	    next.aircraftAutoSortByMaintenance = value.aircraftAutoSortByMaintenance;
122	  }
123	
124	  return Object.keys(next).length > 0 ? next : null;
125	}
126	
127	export function scheduleVisualConfigFromUiPreferences(
128	  uiPreferences: unknown,
129	): PartialScheduleVisualConfig | null {
130	  if (!isRecord(uiPreferences)) return null;
131	
132	  const nested = readScheduleVisualConfig(uiPreferences.scheduleVisualConfig);
133	  if (nested) return nested;
134	
135	  const legacy: PartialScheduleVisualConfig = {};
136	
137	  if (
138	    uiPreferences.scheduleCardDisplay === 'compact' ||
139	    uiPreferences.scheduleCardDisplay === 'expanded'
140	  ) {
141	    legacy.cardDisplayMode = uiPreferences.scheduleCardDisplay;
142	  }
143	
144	  const adminIds = visibleAdminIds(uiPreferences.scheduleAdminVisibility);
145	  if (adminIds !== undefined) legacy.visibleAdminIds = adminIds;
146	
147	  return Object.keys(legacy).length > 0 ? legacy : null;
148	}
149	
150	export function normalizeScheduleVisualConfig(
151	  value: unknown,
152	  fallback: ScheduleVisualConfig = DEFAULT_SCHEDULE_VISUAL_CONFIG,
153	): ScheduleVisualConfig {
154	  const partial = readScheduleVisualConfig(value) ?? {};
155	  return {
156	    axisLayout: partial.axisLayout ?? fallback.axisLayout,
157	    cardDisplayMode: partial.cardDisplayMode ?? fallback.cardDisplayMode,
158	    timelineStartHour: partial.timelineStartHour ?? fallback.timelineStartHour,
159	    visibleResourceTypes:
160	      partial.visibleResourceTypes ?? fallback.visibleResourceTypes,
161	    visibleAdminIds:
162	      partial.visibleAdminIds !== undefined
163	        ? partial.visibleAdminIds
164	        : fallback.visibleAdminIds,
165	    collapsedResourceTypes:
166	      partial.collapsedResourceTypes ?? fallback.collapsedResourceTypes,
167	    viewMode: partial.viewMode ?? fallback.viewMode,
168	    aircraftAutoSortByMaintenance:
169	      partial.aircraftAutoSortByMaintenance ??
170	      fallback.aircraftAutoSortByMaintenance,
171	  };
172	}
173	
174	export function resolveScheduleVisualConfig(
175	  personalConfig: unknown,
176	  schoolConfig: unknown,
177	): ScheduleVisualConfig {
178	  const school = normalizeScheduleVisualConfig(schoolConfig);
179	  return normalizeScheduleVisualConfig(personalConfig, school);
180	}
