1	import * as Sentry from '@sentry/nextjs';
2	import type { MiddlewareHandler } from 'hono';
3	
4	type ScheduleTelemetryEndpoint =
5	  | 'schedule.day'
6	  | 'schedule.all'
7	  | 'schedule.student_training_events'
8	  | 'schedule.module_progress'
9	  | 'schedule.instructor_pending_signoffs'
10	  | 'schedule.instructor_signoff_count'
11	  | 'schedule.standby'
12	  | 'schedule.create'
13	  | 'schedule.update'
14	  | 'schedule.delete';
15	
16	type ScheduleTelemetryRoute = {
17	  endpoint: ScheduleTelemetryEndpoint;
18	  route: string;
19	  locationId: string;
20	};
21	
22	const SCHEDULE_TELEMETRY_SLOW_MS = 2_000;
23	
24	function normalizeScheduleTelemetryPath(path: string): string {
25	  return path.replace(/^\/api(?=\/locations(?:\/|$))/, '');
26	}
27	
28	function classifyScheduleTelemetryRoute(
29	  method: string,
30	  path: string,
31	): ScheduleTelemetryRoute | null {
32	  const normalizedMethod = method.toUpperCase();
33	  const normalizedPath = normalizeScheduleTelemetryPath(path);
34	  const match = /^\/locations\/([^/]+)(?:\/(.*))?$/.exec(normalizedPath);
35	  if (!match) return null;
36	
37	  const [, locationId, tail = ''] = match;
38	  const segments = tail.split('/').filter(Boolean);
39	  const routeBase = '/locations/:locationId';
40	
41	  if (
42	    normalizedMethod === 'GET' &&
43	    segments[0] === 'students' &&
44	    segments[2] === 'training-events'
45	  ) {
46	    return {
47	      endpoint: 'schedule.student_training_events',
48	      route: `${routeBase}/students/:studentId/training-events`,
49	      locationId,
50	    };
51	  }
52	
53	  if (
54	    normalizedMethod === 'GET' &&
55	    segments[0] === 'students' &&
56	    segments[2] === 'module-progress'
57	  ) {
58	    return {
59	      endpoint: 'schedule.module_progress',
60	      route: `${routeBase}/students/:studentId/module-progress`,
61	      locationId,
62	    };
63	  }
64	
65	  if (segments[0] === 'students' && segments[2] === 'standby') {
66	    return {
67	      endpoint: 'schedule.standby',
68	      route: `${routeBase}/students/:studentId/standby`,
69	      locationId,
70	    };
71	  }
72	
73	  if (
74	    normalizedMethod === 'GET' &&
75	    segments[0] === 'instructors' &&
76	    segments[2] === 'pending-signoffs' &&
77	    segments[3] === 'count'
78	  ) {
79	    return {
80	      endpoint: 'schedule.instructor_signoff_count',
81	      route: `${routeBase}/instructors/:instructorId/pending-signoffs/count`,
82	      locationId,
83	    };
84	  }
85	
86	  if (
87	    normalizedMethod === 'GET' &&
88	    segments[0] === 'instructors' &&
89	    segments[2] === 'pending-signoffs'
90	  ) {
91	    return {
92	      endpoint: 'schedule.instructor_pending_signoffs',
93	      route: `${routeBase}/instructors/:instructorId/pending-signoffs`,
94	      locationId,
95	    };
96	  }
97	
98	  if (segments[0] === 'standby' || segments[0] === 'standby-opportunities') {
99	    return {
100	      endpoint: 'schedule.standby',
101	      route:
102	        segments[0] === 'standby-opportunities'
103	          ? `${routeBase}/standby-opportunities`
104	          : `${routeBase}/standby`,
105	      locationId,
106	    };
107	  }
108	
109	  if (segments[0] !== 'schedule') return null;
110	
111	  if (normalizedMethod === 'GET' && segments[1] === 'all') {
112	    return {
113	      endpoint: 'schedule.all',
114	      route: `${routeBase}/schedule/all`,
115	      locationId,
116	    };
117	  }
118	
119	  if (
120	    segments[1] === 'standby' ||
121	    segments[1] === 'standby-by-date' ||
122	    segments[1] === 'standby-aircraft' ||
123	    segments[2] === 'standby'
124	  ) {
125	    return {
126	      endpoint: 'schedule.standby',
127	      route:
128	        segments[1] === 'standby-by-date'
129	          ? `${routeBase}/schedule/standby-by-date`
130	          : segments[1] === 'standby-aircraft'
131	            ? `${routeBase}/schedule/standby-aircraft`
132	            : segments[1] === 'standby'
133	              ? `${routeBase}/schedule/standby`
134	              : `${routeBase}/schedule/:eventId/standby`,
135	      locationId,
136	    };
137	  }
138	
139	  if (normalizedMethod === 'GET' && segments.length === 1) {
140	    return {
141	      endpoint: 'schedule.day',
142	      route: `${routeBase}/schedule`,
143	      locationId,
144	    };
145	  }
146	
147	  if (normalizedMethod === 'POST' && segments.length === 1) {
148	    return {
149	      endpoint: 'schedule.create',
150	      route: `${routeBase}/schedule`,
151	      locationId,
152	    };
153	  }
154	
155	  if (
156	    (normalizedMethod === 'PUT' && segments.length === 2) ||
157	    (normalizedMethod === 'POST' && segments[1] === 'bulk-move')
158	  ) {
159	    return {
160	      endpoint: 'schedule.update',
161	      route:
162	        segments[1] === 'bulk-move'
163	          ? `${routeBase}/schedule/bulk-move`
164	          : `${routeBase}/schedule/:eventId`,
165	      locationId,
166	    };
167	  }
168	
169	  if (normalizedMethod === 'DELETE' && segments.length === 3) {
170	    return {
171	      endpoint: 'schedule.delete',
172	      route: `${routeBase}/schedule/:date/:eventId`,
173	      locationId,
174	    };
175	  }
176	
177	  return null;
178	}
