180	function recordScheduleTelemetry({
181	  endpoint,
182	  route,
183	  locationId,
184	  method,
185	  path,
186	  status,
187	  durationMs,
188	  error,
189	}: ScheduleTelemetryRoute & {
190	  method: string;
191	  path: string;
192	  status: number;
193	  durationMs: number;
194	  error?: unknown;
195	}) {
196	  if (process.env.NODE_ENV === 'test') return;
197	
198	  const rateLimited = status === 429;
199	  const slow = durationMs >= SCHEDULE_TELEMETRY_SLOW_MS;
200	  const payload = {
201	    event: 'schedule_request',
202	    endpoint,
203	    route,
204	    method,
205	    status,
206	    durationMs,
207	    rateLimited,
208	    slow,
209	    locationId,
210	    requestPath: normalizeScheduleTelemetryPath(path),
211	  };
212	
213	  if (rateLimited || slow || error) {
214	    console.warn('[ScheduleTelemetry]', JSON.stringify(payload));
215	  } else {
216	    console.info('[ScheduleTelemetry]', JSON.stringify(payload));
217	  }
218	
219	  if (rateLimited || slow || error) {
220	    Sentry.addBreadcrumb({
221	      category: 'schedule.telemetry',
222	      level: rateLimited || error ? 'warning' : 'info',
223	      message: endpoint,
224	      data: payload,
225	    });
226	  }
227	}
228	
229	export function scheduleTelemetryMiddleware(): MiddlewareHandler {
230	  return async (c, next) => {
231	    const telemetryRoute = classifyScheduleTelemetryRoute(
232	      c.req.method,
233	      c.req.path,
234	    );
235	    if (!telemetryRoute) {
236	      await next();
237	      return;
238	    }
239	
240	    const startedAt = Date.now();
241	    let routeError: unknown;
242	    try {
243	      await next();
244	    } catch (err) {
245	      routeError = err;
246	      throw err;
247	    } finally {
248	      recordScheduleTelemetry({
249	        ...telemetryRoute,
250	        method: c.req.method.toUpperCase(),
251	        path: c.req.path,
252	        status: routeError ? 500 : c.res.status,
253	        durationMs: Date.now() - startedAt,
254	        error: routeError,
255	      });
256	    }
257	  };
258	}
