2198	  if (!targetResource) return null;
2199	  const isExclusiveResource =
2200	    targetResource.type === 'aircraft' ||
2201	    targetResource.type === 'simulator' ||
2202	    targetResource.type === 'instructor' ||
2203	    targetResource.type === 'meeting_room';
2204	  if (!isExclusiveResource) return null;
