2206	  const selectedIds = new Set(targets.map((target) => target.event.id));
2207	  for (let i = 0; i < targets.length; i += 1) {
2208	    for (let j = i + 1; j < targets.length; j += 1) {
2209	      if (
2210	        doScheduleRangesOverlap(
2211	          {
2212	            date: targets[i].event.date,
2213	            startHour: targets[i].startHour,
2214	            endHour: targets[i].endHour,
2215	          },
2216	          {
2217	            date: targets[j].event.date,
2218	            startHour: targets[j].startHour,
2219	            endHour: targets[j].endHour,
2220	          },
2221	        )
2222	      ) {
2223	        return {
2224	          targetResource,
2225	          movingEvent: targets[i].event,
2226	          conflictEvent: targets[j].event,
2227	        };
2228	      }
2229	    }
2230	  }
2231	
2232	  const eventUsesTargetResource = (event: ScheduleEvent) => {
2233	    if (
2234	      targetResource.type === 'aircraft' ||
2235	      targetResource.type === 'simulator'
2236	    ) {
2237	      return (
2238	        event.aircraftId === targetResource.id ||
2239	        event.resourceId === targetResource.id
2240	      );
2241	    }
