44	export const hangarLayoutRepository = {
45	  /** Load the layout config for a location (or null if none yet). */
46	  async getLayout(
47	    orgId: string,
48	    locationId: string,
49	  ): Promise<LayoutRecord | null> {
50	    if (!isUuid(orgId) || !isUuid(locationId)) return null;
51	    try {
52	      const row = await db
53	        .select()
54	        .from(schema.hangarLayouts)
55	        .where(
56	          and(
57	            eq(schema.hangarLayouts.flightSchoolId, orgId),
58	            eq(schema.hangarLayouts.locationId, locationId),
59	          ),
60	        )
61	        .limit(1);
62	      const l = row[0];
63	      if (!l) return null;
64	      return {
65	        id: l.id,
66	        templateKey: l.templateKey,
67	        zones: l.zones ?? [],
68	        obstacles: l.obstacles ?? [],
69	        worldW: Number(l.worldW),
70	        worldH: Number(l.worldH),
71	        showGrid: l.showGrid,
72	        updatedAt: l.updatedAt.toISOString(),
73	      };
74	    } catch (err) {
75	      console.error(
76	        '[hangarLayoutRepository.getLayout] failed:',
77	        safeErrorMessage(err),
78	      );
79	      throw err;
80	    }
81	  },
82	
83	  /** Upsert layout config (zones + obstacles + template + bounds) for a location. */
84	  async upsertLayout(
85	    orgId: string,
86	    locationId: string,
87	    data: {
88	      templateKey: string;
89	      zones: HangarZone[];
90	      obstacles?: HangarObstruction[];
91	      worldW: number;
92	      worldH: number;
93	      showGrid?: boolean;
94	      userId?: string;
95	    },
96	  ): Promise<LayoutRecord> {
97	    const existing = await db
98	      .select({ id: schema.hangarLayouts.id })
99	      .from(schema.hangarLayouts)
100	      .where(eq(schema.hangarLayouts.locationId, locationId))
101	      .limit(1);
102	
103	    if (existing[0]) {
104	      const updated = await db
105	        .update(schema.hangarLayouts)
106	        .set({
107	          templateKey: data.templateKey,
108	          zones: data.zones,
109	          obstacles: data.obstacles ?? [],
110	          worldW: String(data.worldW),
111	          worldH: String(data.worldH),
112	          showGrid: data.showGrid ?? false,
113	          updatedAt: new Date(),
114	          updatedByUserId: data.userId ?? null,
115	        })
116	        .where(
117	          and(
118	            eq(schema.hangarLayouts.flightSchoolId, orgId),
119	            eq(schema.hangarLayouts.locationId, locationId),
120	          ),
121	        )
122	        .returning();
123	      const l = updated[0];
124	      return {
125	        id: l.id,
126	        templateKey: l.templateKey,
127	        zones: l.zones ?? [],
128	        obstacles: l.obstacles ?? [],
129	        worldW: Number(l.worldW),
130	        worldH: Number(l.worldH),
131	        showGrid: l.showGrid,
132	        updatedAt: l.updatedAt.toISOString(),
133	      };
134	    }
135	
136	    const inserted = await db
137	      .insert(schema.hangarLayouts)
138	      .values({
139	        flightSchoolId: orgId,
140	        locationId,
141	        templateKey: data.templateKey,
142	        zones: data.zones,
143	        obstacles: data.obstacles ?? [],
144	        worldW: String(data.worldW),
145	        worldH: String(data.worldH),
146	        showGrid: data.showGrid ?? false,
147	        updatedByUserId: data.userId ?? null,
148	      })
149	      .returning();
150	    const l = inserted[0];
151	    return {
152	      id: l.id,
153	      templateKey: l.templateKey,
154	      zones: l.zones ?? [],
155	      obstacles: l.obstacles ?? [],
156	      worldW: Number(l.worldW),
157	      worldH: Number(l.worldH),
158	      showGrid: l.showGrid,
159	      updatedAt: l.updatedAt.toISOString(),
160	    };
161	  },
