128	  const fetchAll = useCallback(async () => {
129	    if (!locationId) return;
130	    setLoading(true);
131	    setError(null);
132	    try {
133	      const [layoutRes, equipRes] = await Promise.all([
134	        fetch(`${SERVER_API_BASE}/locations/${locationId}/hangar-layout`, {
135	          credentials: 'include',
136	        }),
137	        fetch(`${SERVER_API_BASE}/locations/${locationId}/equipment`, {
138	          credentials: 'include',
139	        }),
140	      ]);
141	      if (!layoutRes.ok) {
142	        if (layoutRes.status === 403) {
143	          throw new Error('Feature is not enabled for this school');
144	        }
145	        throw new Error(`Layout HTTP ${layoutRes.status}`);
146	      }
147	      if (!equipRes.ok) throw new Error(`Equipment HTTP ${equipRes.status}`);
148	      const layoutData = await layoutRes.json();
149	      const equipData = await equipRes.json();
150	      setLayout(layoutData.layout ?? null);
151	      setPositions(layoutData.positions ?? []);
152	      setShowGrid(Boolean(layoutData.layout?.showGrid));
