166	  // Best-effort make/model lookup for FAA class → visual silhouette.
167	  useEffect(() => {
168	    let cancelled = false;
169	    async function run() {
170	      if (!locationId || equipment.length === 0) return;
171	      try {
172	        const schoolSlice = equipment[0]; // orgId is implicit in session
173	        if (!schoolSlice) return;
174	        // We don't have schoolId on the client for this endpoint, so skip
175	        // the lookup unless one is present in the URL. The classifier still
176	        // works from make/model string patterns alone (see classify.ts).
177	        setMakeModels([]);
178	      } catch {
179	        if (!cancelled) setMakeModels([]);
180	      }
181	    }
182	    run();
183	    return () => {
184	      cancelled = true;
185	    };
186	  }, [locationId, equipment]);
