188	  useEffect(() => {
189	    fetchAll();
190	  }, [fetchAll]);
191	
192	  // Merge equipment + positions → planes.
193	  const planes = useMemo<Plane[]>(() => {
194	    const posMap = new Map(positions.map((p) => [p.equipmentId, p]));
195	    const zones = layout?.zones ?? [];
196	    const operationalZones = aircraftOperationalZones(zones);
197	    const firstZone = operationalZones[0];
198	
199	    return equipment.map((e, idx) => {
200	      const pos = posMap.get(e.id);
201	      const local = localPlanes[e.id];
202	      const cls = makeModels.find(
203	        (m) =>
204	          (m.make ?? '').toLowerCase() === (e.make ?? '').toLowerCase() &&
205	          (m.model ?? '').toLowerCase() === (e.model ?? '').toLowerCase(),
206	      )?.class;
207	
208	      // Resolve visual spec priority chain:
209	      // 1. Explicit catalog key set by user (highest fidelity)
210	      // 2. Auto-match make/model to catalog (correct color + real dimensions)
211	      // 3. Broad pattern classifier (correct silhouette/engine count, generic color)
212	      // 4. UNKNOWN_SPEC gray (when make/model is empty or unrecognized)
213	      const aircraftTypeKey =
214	        local?.aircraftTypeKey ?? pos?.aircraftTypeKey ?? null;
215	      const autoCatalogKey =
216	        aircraftTypeKey ?? classifyByCatalogKey(e.make, e.model);
217	      const catalogSpec = autoCatalogKey
218	        ? specForCatalogKey(autoCatalogKey)
219	        : null;
220	      const visualType = classifyHangarVisual({
221	        make: e.make,
222	        model: e.model,
223	        class: cls,
224	        override: e.hangarVisualOverride,
225	      });
226	      const spec: VisualSpec =
227	        catalogSpec ??
228	        (hasKnownPattern(e.make, e.model) ? specFor(visualType) : UNKNOWN_SPEC);
229	
230	      // Local state wins over server state so drag and rotation updates are
231	      // immediately visible without waiting for the save round-trip.
232	      let x = local?.x ?? pos?.x;
233	      let y = local?.y ?? pos?.y;
234	      if (x === undefined || y === undefined) {
235	        // Unplaced: stack them in a grid inside the first zone (if any),
236	        // otherwise at (20 + idx * 10, 20).
237	        if (firstZone) {
238	          const cols = Math.max(
239	            1,
240	            Math.floor(firstZone.w / Math.max(spec.wingspan + 3, 10)),
241	          );
242	          const col = idx % cols;
243	          const row = Math.floor(idx / cols);
244	          x = firstZone.x + 8 + col * Math.max(spec.wingspan + 3, 10);
245	          y = firstZone.y + 10 + row * Math.max(spec.length + 3, 10);
246	        } else {
